function LiveDriverMap({ locations }: { locations: AnyRecord[] }) {
  const container = useRef<HTMLDivElement>(null)
  const map = useRef<any>(null)
  const markers = useRef<any[]>([])
  const hasFitted = useRef(false)
  const [mapError, setMapError] = useState('')
  const [mapReady, setMapReady] = useState(false)
  useEffect(() => {
    let cancelled = false
    if (!mapsKey) { setMapError('Falta NEXT_PUBLIC_GOOGLE_MAPS_API_KEY en Render.'); return }
    void loadGoogleMaps().then(maps => {
      if (cancelled || !container.current) return
      map.current = new maps.Map(container.current, { center: { lat: -32.883, lng: -68.84 }, zoom: 12, mapTypeControl: false, streetViewControl: false, fullscreenControl: true })
      setMapReady(true)
    }).catch(error => { if (!cancelled) setMapError(error instanceof Error ? error.message : 'Google Maps no disponible.') })
    return () => { cancelled = true; markers.current.forEach(marker => marker.setMap(null)); markers.current = []; map.current = null }
  }, [])
  useEffect(() => {
    if (!mapReady || !map.current || !window.google?.maps) return
    markers.current.forEach(marker => marker.setMap(null))
    const points = (locations || []).map(location => ({ location, lat: Number(location.lat), lon: Number(location.lon ?? location.lng) })).filter(point => Number.isFinite(point.lat) && Number.isFinite(point.lon))
    if (!points.length) { markers.current = []; hasFitted.current = false; return }
    const maps = window.google.maps
    markers.current = points.map(({ location, lat, lon }) => new maps.Marker({ map: map.current, position: { lat, lng: lon }, title: location.driver_name || location.driver_username || 'Repartidor', zIndex: 30, icon: { path: maps.SymbolPath.CIRCLE, scale: 8, fillColor: '#10b981', fillOpacity: 0.98, strokeColor: '#064e3b', strokeOpacity: 0.95, strokeWeight: 2 }, label: { text: String(location.driver_name || location.driver_username || 'R').slice(0, 1).toUpperCase(), color: '#ffffff', fontSize: '10px', fontWeight: '700' } }))
    if (!hasFitted.current) {
      const bounds = new maps.LatLngBounds()
      points.forEach(point => bounds.extend({ lat: point.lat, lng: point.lon }))
      if (points.length === 1) { map.current.setCenter({ lat: points[0].lat, lng: points[0].lon }); map.current.setZoom(15) } else map.current.fitBounds(bounds, 64)
      hasFitted.current = true
    }
  }, [locations, mapReady])
  return <div className="relative min-h-[420px] overflow-hidden rounded-xl bg-slate-100"><div ref={container} className="absolute inset-0" />{mapError && <div className="absolute inset-x-4 top-4 rounded-xl border border-amber-200 bg-white/95 p-3 text-sm text-amber-800 shadow-sm">{mapError}</div>}{!locations.length && <div className="pointer-events-none absolute inset-x-4 bottom-4 rounded-xl bg-white/90 p-3 text-sm text-slate-600 shadow-sm">Mapa listo. No hay ubicaciones recientes para mostrar.</div>}</div>
}
