function Deliveries({ deliveries, onReload }: { deliveries: Order[]; onReload: () => void }) {
  const [driverFilter, setDriverFilter] = useState('')
  const drivers = useMemo(() => Array.from(new Set(deliveries.map(order => String(order.delivered_by_username || order.assigned_driver_username || '').trim()).filter(Boolean))).sort(), [deliveries])
  const filtered = deliveries.filter(order => !driverFilter || String(order.delivered_by_username || order.assigned_driver_username || '') === driverFilter)
  return <div className="space-y-5"><PageTitle title="Entregas" description="Historial de entregas confirmadas por los repartidores." action={<button onClick={onReload} className="secondary-button"><RefreshCw className="size-4" />Actualizar</button>} /><Card className="overflow-hidden"><div className="flex flex-wrap gap-3 border-b border-slate-100 p-4"><select value={driverFilter} onChange={event => setDriverFilter(event.target.value)} className="field max-w-xs"><option value="">Todos los repartidores</option>{drivers.map(driver => <option key={driver} value={driver}>{driver}</option>)}</select></div><div className="overflow-x-auto"><table className="data-table"><thead><tr><th>Pedido</th><th>Entregado por</th><th>Fecha y hora</th><th>Cliente</th><th>Dirección</th><th>Importe</th><th>Estado</th></tr></thead><tbody>{filtered.length ? filtered.map(order => <tr key={String(order.id)}><td className="font-semibold text-slate-800">#{order.id}</td><td>{order.delivered_by_username || order.assigned_driver_username || 'Sin identificar'}</td><td className="whitespace-nowrap text-slate-600">{date(order.delivered_at || order.last_delivery_issue_at || order.created_at)}</td><td><p className="font-medium text-slate-700">{order.user_full_name || 'Cliente'}</p><p className="text-[11px] text-slate-400">{order.user_email || '—'}</p></td><td className="max-w-xs text-slate-600">{[order.user_calle, order.user_numeracion, order.user_barrio, order.user_department].filter(Boolean).join(' ') || 'Sin dirección'}</td><td className="font-semibold">{money(order.total)}</td><td><Pill tone={String(order.status || '') === 'entregado' ? 'green' : 'amber'}>{statusLabels[order.status || ''] || order.status || 'Incidencia'}</Pill></td></tr>) : <tr><td colSpan={7}><Empty message="Todavía no hay entregas registradas." /></td></tr>}</tbody></table></div></Card></div>
}

